import java.util.*;

class Solution {
    public List<Integer> flatten(int[] vals, int[] next, int[] child) {
        List<Integer> res = new ArrayList<>();
        if (vals.length == 0) return res;
        Deque<Integer> stack = new ArrayDeque<>();
        stack.push(0);                                   // top layer starts at node 0
        while (!stack.isEmpty()) {
            int u = stack.pop();
            res.add(vals[u]);
            if (next[u] != -1) stack.push(next[u]);      // continue later
            if (child[u] != -1) stack.push(child[u]);    // child layer comes first
        }
        return res;
    }
}

