class Solution:
    def flatten(self, vals: List[int], next: List[int], child: List[int]) -> List[int]:
        out = []; st = [0] if vals else []
        while st:
            c = st.pop()
            out.append(vals[c])
            if next[c] != -1: st.append(next[c])
            if child[c] != -1: st.append(child[c])
        return out
